(6833609, 1027215, 58691, '<td valign="top">Unique title for this image - reference of silence to an incredibly "noisy" image. Love it! Nicely done. Cropping and spacing of the subjects is wonderful. Good job.</td>', 'Unique title for this image - reference of silence to an incredibly "noisy" image. Love it! Nicely done. Cropping and spacing of the subjects is wonderful. Good job.', '2012-08-02 14:11:33.000000', NULL, 1),
(6833618, 1027950, 62249, '<td valign="top">Not exactly a proverb, but an interesting photo nonetheless. The shadow on the right part of the computer screen is distracting, but your composition (curved page, keyboard, and screen forming foreground, mid ground, background) is good and so is your DOF.</td>', 'Not exactly a proverb, but an interesting photo nonetheless. The shadow on the right part of the computer screen is distracting, but your composition (curved page, keyboard, and screen forming foreground, mid ground, background) is good and so is your DOF.', '2012-08-02 14:25:30.000000', NULL, 1),
(6833619, 1027347, 62249, '<td valign="top">Good catch light in bird''s eye. Image is very contrasty overall.</td>', 'Good catch light in bird''s eye. Image is very contrasty overall.', '2012-08-02 14:27:33.000000', NULL, 1),
(6833620, 1028043, 62249, '<td valign="top">Good concept. The reflected bright dot near lower edge is distracting. Since this was advanced editing, I think you could''ve cloned that out. Try a little more DOF on the candy wrapper at right. It''s a bit blurry.</td>', 'Good concept. The reflected bright dot near lower edge is distracting. Since this was advanced editing, I think you could''ve cloned that out. Try a little more DOF on the candy wrapper at right. It''s a bit blurry.', '2012-08-02 14:31:09.000000', NULL, 1),
(6833623, 1028315, 62249, '<td valign="top">Heh. The pawns look like penguins. I like the composition. Maybe try more contrast and more saturation to make it dramatic.</td>', 'Heh. The pawns look like penguins. I like the composition. Maybe try more contrast and more saturation to make it dramatic.', '2012-08-02 14:32:42.000000', NULL, 1),
(6833626, 1027334, 62249, '<td valign="top">Nice. Maybe adjust curves to darken the background a little more to make the web really pop.</td>', 'Nice. Maybe adjust curves to darken the background a little more to make the web really pop.', '2012-08-02 14:34:35.000000', NULL, 1),
(6833631, 1027462, 62249, '<td valign="top">This is fine as a snapshot that records what a place looks like, but it doesn''t tell much of a story. Try a composition that leads a viewer''s eye through the image. This composition doesn''t really help me figure out what I should look at. The house, especially the blown out highlight? The palm trees? The bridge? The reflection? The flagpole that either needs more space to the left of it or needs to be cropped out entirely?</td>', 'This is fine as a snapshot that records what a place looks like, but it doesn''t tell much of a story. Try a composition that leads a viewer''s eye through the image. This composition doesn''t really help me figure out what I should look at. The house, especially the blown out highlight? The palm trees? The bridge? The reflection? The flagpole that either needs more space to the left of it or needs to be cropped out entirely?', '2012-08-02 14:39:40.000000', NULL, 1),
(6833633, 1028252, 62249, '<td valign="top">Would make a good stock photo. Soft focus works well.</td>', 'Would make a good stock photo. Soft focus works well.', '2012-08-02 14:40:48.000000', NULL, 1),
